"use client";
import type { ReactNode } from "react";
import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import "./toast.css";

type Tone = "neutral" | "success" | "error";
interface ToastItem {
  id: number;
  title: ReactNode;
  description?: ReactNode;
  tone: Tone;
  action?: { label: string; onClick: () => void };
  duration: number;
}
let items: ToastItem[] = [];
let nextId = 1;
const listeners = new Set<() => void>();
const emit = () => listeners.forEach((l) => l());
/** Show a toast from anywhere. Returns its id. Render <Toaster /> once in your app. */
export function toast(
  title: ReactNode,
  options: { description?: ReactNode; tone?: Tone; action?: ToastItem["action"]; duration?: number } = {},
) {
  const id = nextId++;
  items = [...items, { id, title, tone: "neutral" as Tone, duration: 4000, ...options }].slice(-5);
  emit();
  return id;
}
toast.dismiss = (id: number) => {
  items = items.filter((t) => t.id !== id);
  emit();
};
const subscribe = (l: () => void) => (listeners.add(l), () => listeners.delete(l));

function ToastCard({ t, index, count, expanded, paused }: { t: ToastItem; index: number; count: number; expanded: boolean; paused: boolean }) {
  const [drag, setDrag] = useState(0);
  const start = useRef<number | null>(null);
  const left = useRef(t.duration);
  useEffect(() => {
    if (paused) return;
    const began = Date.now();
    const timer = setTimeout(() => toast.dismiss(t.id), left.current);
    return () => {
      clearTimeout(timer);
      left.current -= Date.now() - began;
    };
  }, [paused, t.id]);
  const depth = count - 1 - index;
  return (
    <li
      className="forme-toast"
      data-tone={t.tone}
      style={{
        ["--forme-toast-depth" as string]: depth,
        ["--forme-toast-drag" as string]: `${drag}px`,
        zIndex: index,
      }}
      data-hidden={!expanded && depth > 2 ? "" : undefined}
      onPointerDown={(e) => {
        if ((e.target as Element).closest("button")) return;
        start.current = e.clientX;
        e.currentTarget.setPointerCapture(e.pointerId);
      }}
      onPointerMove={(e) => start.current !== null && setDrag(Math.max(0, e.clientX - start.current))}
      onPointerUp={() => {
        if (drag > 90) toast.dismiss(t.id);
        start.current = null;
        setDrag(0);
      }}
    >
      <span className="forme-toast-dot" aria-hidden="true" />
      <div className="forme-toast-body">
        <strong>{t.title}</strong>
        {t.description && <p>{t.description}</p>}
      </div>
      {t.action && (
        <button
          type="button"
          className="forme-toast-action"
          onClick={() => {
            t.action!.onClick();
            toast.dismiss(t.id);
          }}
        >
          {t.action.label}
        </button>
      )}
      <button type="button" className="forme-toast-close" aria-label="Dismiss notification" onClick={() => toast.dismiss(t.id)}>
        ×
      </button>
    </li>
  );
}
/** The stack. Hover or focus expands it and pauses the timers; swipe right to dismiss. */
export function Toaster({ className = "" }: { className?: string }) {
  const list = useSyncExternalStore(subscribe, () => items, () => items);
  const [expanded, setExpanded] = useState(false);
  return (
    <section aria-label="Notifications" className={`forme-toaster ${className}`}>
      <ol
        role="status"
        aria-live="polite"
        data-expanded={expanded || undefined}
        style={{ ["--forme-toast-count" as string]: list.length }}
        onPointerEnter={() => setExpanded(true)}
        onPointerLeave={() => setExpanded(false)}
        onFocus={() => setExpanded(true)}
        onBlur={(e) => !e.currentTarget.contains(e.relatedTarget) && setExpanded(false)}
      >
        {list.map((t, i) => (
          <ToastCard key={t.id} t={t} index={i} count={list.length} expanded={expanded} paused={expanded} />
        ))}
      </ol>
    </section>
  );
}

.forme-toaster {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 1000;
  width: min(360px, calc(100vw - 40px));
  color: #f4f4f5;
  font-size: 14px;
}
.forme-toaster ol {
  display: grid;
  margin: 0;
  padding: 0;
  list-style: none;
}
.forme-toast {
  --forme-toast-y: calc(var(--forme-toast-depth) * -10px);
  --forme-toast-scale: calc(1 - var(--forme-toast-depth) * 0.05);
  grid-area: 1 / 1;
  align-self: end;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  box-sizing: border-box;
  padding: 14px 14px 14px 16px;
  border-radius: 14px;
  background: linear-gradient(180deg, #1c1c21, #131316);
  box-shadow:
    inset 0 0 0 1px #ffffff17,
    inset 0 1px 0 #ffffff12,
    0 16px 40px -12px #000000b3;
  transform: translate(var(--forme-toast-drag), var(--forme-toast-y)) scale(var(--forme-toast-scale));
  transform-origin: bottom center;
  opacity: calc(1 - var(--forme-toast-depth) * 0.18);
  touch-action: pan-y;
  transition:
    transform 0.45s cubic-bezier(0.2, 0.9, 0.2, 1),
    opacity 0.3s;
  animation: forme-toast-in 0.45s cubic-bezier(0.2, 0.9, 0.2, 1);
}
.forme-toast[data-hidden] {
  opacity: 0;
  pointer-events: none;
}
/* Expanded, the stack fans out into a readable column. */
.forme-toaster ol[data-expanded] .forme-toast {
  --forme-toast-y: calc(var(--forme-toast-depth) * -100% - var(--forme-toast-depth) * 8px);
  --forme-toast-scale: 1;
  opacity: 1;
}
.forme-toast-dot {
  flex-shrink: 0;
  width: 8px;
  height: 8px;
  margin-top: 6px;
  border-radius: 50%;
  background: #a1a1aa;
}
.forme-toast[data-tone="success"] .forme-toast-dot {
  background: #4ade80;
  box-shadow: 0 0 10px #4ade80;
}
.forme-toast[data-tone="error"] .forme-toast-dot {
  background: #f87171;
  box-shadow: 0 0 10px #f87171;
}
.forme-toast-body {
  flex: 1;
  min-width: 0;
}
.forme-toast-body strong {
  display: block;
  font-weight: 500;
}
.forme-toast-body p {
  margin: 3px 0 0;
  color: #a1a1aa;
  line-height: 1.45;
}
.forme-toast-action,
.forme-toast-close {
  flex-shrink: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}
.forme-toast-action {
  height: 28px;
  padding: 0 10px;
  border-radius: 8px;
  background: #ffffff14;
  font-size: 13px;
  font-weight: 500;
}
.forme-toast-close {
  width: 22px;
  height: 22px;
  border-radius: 6px;
  color: #71717a;
  font-size: 18px;
  line-height: 1;
}
.forme-toast-close:hover {
  color: #f4f4f5;
}
.forme-toast button:focus-visible {
  outline: 2px solid #f4f4f5;
  outline-offset: 2px;
}
@keyframes forme-toast-in {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.96);
  }
}
@media (prefers-reduced-motion: reduce) {
  .forme-toast {
    transition: none;
    animation: none;
  }
}
